import { atom, read, update } from 'claude-code'
import type { EngineInterface, PromptOrigin, Register } from 'claude-code'

import type { Item, PaneView } from '../types'
import {
  added,
  afterFill,
  asked,
  cancelled,
  canDefault,
  committed,
  defaultAnswer,
  dismissed,
  isLive,
  lineFor,
  looked,
  message,
  queue,
  readied,
  reopened,
  restored,
  sent,
  submitted,
  toChange,
  undone,
} from './answers'
import { askPrompt } from './ask'
import { keepFocusOn } from './focus'
import { parseReply } from './haiku'
import { checkLooks, LOOKS_RULES, looksPrompt } from './looks'
import { hasMarker } from './parse'
import type { RebuiltReply } from './rebuild'
import { rebuilt, repliesIn } from './rebuild'

const PANE = 'questions'
const TITLE = 'Questions'
// Sessions kept in $.store (4 MiB in all); the oldest go first.
const KEPT_SESSIONS = 30
const DEFAULT_VIEW: PaneView = {
  tab: 'needs',
  collapsed: [],
  expanded: [],
  preview: false,
  asking: [],
  foldedThreads: [],
  rebuild: '',
}
// Replies a rebuild reads, newest first: one Haiku call each, and one more for
// each that the person wrote after.
const REBUILD_REPLIES = 20
const items = atom({ plugin: 'question-pane', key: 'list' } as const, [])
const view = atom({ plugin: 'question-pane', key: 'pane' } as const, DEFAULT_VIEW)
const drafts = atom({ plugin: 'question-pane', key: 'drafts' } as const, {})

// Prompts that are not the person's own words.
const NOT_THE_PERSON: ReadonlySet<PromptOrigin['kind']> = new Set(['plugin', 'task-notification', 'scheduled-trigger'])

const KIND = { question: 'Question', decision: 'Decision', review: 'Review' } as const

function clock(at: number): string {
  const d = new Date(at)

  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

// The pane's view, with any field an older version did not save at its default.
async function readView($: EngineInterface): Promise<PaneView> {
  return { ...DEFAULT_VIEW, ...(await read($, view)) }
}

function toggled(list: readonly string[], id: string): string[] {
  return list.includes(id) ? list.filter(x => x !== id) : [...list, id]
}

async function save($: EngineInterface): Promise<void> {
  const key = `session:${await $.session.id()}`
  await $.store.set(key, await read($, items))
  const sessions = (await $.store.keys()).filter(k => k.startsWith('session:'))
  for (const old of sessions.slice(0, Math.max(0, sessions.length - KEPT_SESSIONS))) {
    await $.store.delete(old)
  }
}

async function change($: EngineInterface, fn: (list: Item[], at: number) => Item[]): Promise<void> {
  const at = await $.clock.now()
  await update($, items, list => fn(list, at))
  await save($)
}

async function haiku($: EngineInterface, system: string, prompt: string): Promise<string | undefined> {
  const r = await $.model.complete({ model: 'haiku', system, prompt, maxTokens: 8000, timeoutMs: 60_000 })

  return r.isAnswered ? r.text : undefined
}

async function openPane($: EngineInterface): Promise<void> {
  if (!(await $.ui.panes()).some(p => p.id === PANE)) await $.ui.open({ id: PANE, title: TITLE })
}

async function answer($: EngineInterface, id: string, text: string, what: string): Promise<void> {
  await change($, (list, at) => readied(list, new Map([[id, text]]), what, at))
  await update($, drafts, old => Object.fromEntries(Object.entries(old).filter(([key]) => key !== id)))
}

// "Ask about this": a fork of the conversation answers, told which question it
// is about; the exchange stays on the item, never in the conversation.
async function askAbout($: EngineInterface, id: string, question: string): Promise<void> {
  const item = (await read($, items)).find(i => i.id === id)
  if (item === undefined) return
  const now = await $.clock.now()
  await update($, items, list => asked(list, id, { who: 'you', text: question, at: now }))
  await update($, view, v => ({ ...v, asking: [...v.asking, id] }))
  const r = await $.model.fork({ prompt: askPrompt(item, question, clock(item.at)) })
  const text = r.isAnswered
    ? r.text.trim()
    : `No answer: ${r.reason === 'nothing-to-fork' ? 'there is no conversation to fork yet' : r.reason}.`
  const at = await $.clock.now()
  await update($, items, list => asked(list, id, { who: 'fork', text, at }))
  await update($, view, v => ({ ...v, asking: v.asking.filter(x => x !== id) }))
  await save($)
}

// A review asks to be approved, or, when the agent already acted, ratified.
const approveWord = (i: Item) => (i.title.startsWith('taken') ? 'Ratify' : 'Approve')

// The actions that are safe to run twice, by their Button's key: each checks
// the item is still in the state the action is for, so a second run does
// nothing. The pane's buttons run them, and so does a click that only gave
// the pane the keyboard (D33).
async function runSafeAction($: EngineInterface, element: string): Promise<boolean> {
  if (element === 'rebuild') {
    // Not awaited: the rebuild runs on, showing its progress in the pane.
    void rebuild($)
    return true
  }
  const [action, turnId, code, index] = element.split(':')
  const id = `${turnId}:${code}`
  const item = (await read($, items)).find(i => i.id === id)
  if (item === undefined) return false
  const isOpen = item.status === 'open' || item.status === 'looks'
  switch (action) {
    case 'default':
      if (!canDefault(item)) return false
      await answer($, id, defaultAnswer(item), 'Default taken in the pane')
      return true
    case 'option': {
      const option = item.options[Number(index)]
      if (!isOpen || option === undefined) return false
      await answer($, id, option.label, 'Option picked in the pane')
      return true
    }
    case 'yes': {
      if (!isOpen) return false
      const yes = approveWord(item)
      await answer($, id, yes.toLowerCase(), `${yes} in the pane`)
      return true
    }
    case 'reverse':
      if (!isOpen) return false
      await answer($, id, 'reverse', 'Reverse in the pane')
      return true
    case 'commit':
      if (item.status !== 'looks') return false
      await change($, (l, at) => committed(l, id, at))
      return true
    case 'cancel':
      if (item.status !== 'looks') return false
      await change($, (l, at) => cancelled(l, id, at))
      return true
    case 'dismiss':
      if (!isLive(item)) return false
      await change($, (l, at) => dismissed(l, id, at))
      return true
    default:
      return false
  }
}

// Whether the pane held the keyboard when last drawn; and the last click that
// only gave it the keyboard and ran its action, whose real press, should one
// follow, is dropped. Module variables: a reload starts them over.
let isPaneFocused = true
let ranOnFocus: { element: string; at: number } | undefined

// Parses the agent's recent replies again and merges their items into the
// list; then asks Haiku which new items the person's later messages answered,
// so a question answered long ago comes back as "Looks answered", not open.
async function rebuild($: EngineInterface): Promise<void> {
  if ((await readView($)).rebuild !== '') return
  const progress = (text: string) => update($, view, v => ({ ...v, rebuild: text }))
  await progress('Reading the conversation…')
  try {
    const replies = repliesIn(await $.session.messages(), hasMarker, REBUILD_REPLIES)
    $.ui.toast(
      replies.length === 0
        ? 'Rebuild: no reply in the conversation asks a question.'
        : `Rebuild: reading ${replies.length} ${replies.length === 1 ? 'reply' : 'replies'} with Haiku.`,
    )
    const parsed: RebuiltReply[] = []
    for (const [index, reply] of replies.entries()) {
      await progress(`Reading reply ${index + 1} of ${replies.length} with Haiku…`)
      const { topic, items: found } = await parseReply(reply.text, (system, prompt) => haiku($, system, prompt))
      parsed.push({ index, topic, items: found, after: reply.after })
    }
    const now = await $.clock.now()
    let counts = { added: 0, refreshed: 0 }
    await update($, items, list => {
      const result = rebuilt(list, parsed, now)
      counts = { added: result.added, refreshed: result.refreshed }
      return result.list
    })
    let looks = 0
    const answeredLater = parsed.filter(r => r.after.trim() !== '')
    for (const [n, reply] of answeredLater.entries()) {
      const open = (await read($, items)).filter(i => i.turnId === `rebuilt-${reply.index}` && i.status === 'open')
      if (open.length === 0) continue
      await progress(`Checking what you wrote after reply ${reply.index + 1} (${n + 1} of ${answeredLater.length})…`)
      const answerText = await haiku($, LOOKS_RULES, looksPrompt(open, reply.after))
      const found = answerText === undefined ? new Map<string, string>() : checkLooks(answerText, reply.after, open)
      looks += found.size
      if (found.size > 0) await change($, (list, at) => looked(list, found, at))
    }
    await save($)
    $.ui.toast(
      `Rebuilt from ${replies.length} replies: ${counts.added} new, ${counts.refreshed} refreshed, ${looks} looking answered by what you wrote.`,
    )
  } catch (error) {
    $.ui.toast(`Rebuild stopped: ${error instanceof Error ? error.message : String(error)}`)
  } finally {
    await progress('')
  }
}

// Puts the ready answers in the prompt box for the person to send. Where the
// session draws no box, submits them as the person's words and marks them sent.
async function send($: EngineInterface): Promise<void> {
  const list = await read($, items)
  const text = message(list)
  if (text === '') return
  const box = await $.prompt.read()
  const hasDraft = box.text.trim() !== ''
  const filled = await $.prompt.fill({ text: hasDraft ? `\n\n${text}` : text, mode: hasDraft ? 'append' : 'replace' })
  const next = afterFill(filled)
  if (next === 'filled') {
    await update($, view, v => ({ ...v, preview: false }))
    $.ui.toast('Your answers are in the prompt box: press Enter to send them.')
  } else if (next === 'submit') {
    await $.prompt.submit({ text, asUser: true })
    await change($, (l, at) => sent(l, new Set(queue(list).map(i => i.id)), at))
    $.ui.toast('Your answers were sent.')
  } else {
    $.ui.toast(
      next === 'dialog'
        ? 'Close the open dialog, then press Send again.'
        : 'The prompt box did not take your answers; they are still ready.',
    )
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'questions',
      description: 'Show the questions you have not answered yet',
      argumentHint: '[rebuild]',
    })
    // A hot reload keeps $.state; a resumed session, or a list saved under an
    // older shape, is taken from $.store.
    if ((await read($, items)).length === 0) {
      const saved = restored(await $.store.get(`session:${await $.session.id()}`))
      if (saved !== undefined && saved.length > 0) await update($, items, () => saved)
    }
    if ((await read($, items)).some(isLive)) await openPane($)

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    // /clear: the conversation ends and the process goes on under a new id;
    // the old list stays saved under the old one.
    if (e.reason === 'clear') {
      await update($, items, () => [])
      await update($, view, () => DEFAULT_VIEW)
      await update($, drafts, () => ({}))
    }

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined || e.reason !== 'answer' || !hasMarker(e.answer)) return result
    const parsed = await parseReply(e.answer, (system, prompt) => haiku($, system, prompt))
    if (parsed.items.length === 0) return result
    await change($, (list, at) => added(list, parsed.items, e.turnId, parsed.topic, at))
    await openPane($)

    return result
  })

  // The person's prompt enters first; then the list learns from it: a ready
  // answer sent unchanged is sent, a line led by a code looks like an answer,
  // and Haiku is asked which other open questions it answers.
  on('prompt.submit', async ($, e, next) => {
    const result = await next(e)
    if (NOT_THE_PERSON.has(e.origin.kind) || e.text.trim() === '') return result
    await change($, (list, at) => submitted(list, e.text, at))
    const open = (await read($, items)).filter(i => i.status === 'open')
    if (open.length === 0) return result
    const answerText = await haiku($, LOOKS_RULES, looksPrompt(open, e.text))
    if (answerText === undefined) return result
    const found = checkLooks(answerText, e.text, open)
    if (found.size > 0) await change($, (list, at) => looked(list, found, at))

    return result
  }).catch(($, e, next) => next(e))

  // The editor posts each change, kept as the item's draft, and Ctrl+Enter.
  on('ui.message', async ($, e, next) => {
    if (!e.element.startsWith('editor:')) return next(e)
    const id = e.element.slice('editor:'.length)
    const data = e.data
    if (typeof data !== 'object' || data === null || !('kind' in data) || !('text' in data)) return {}
    const text = typeof data.text === 'string' ? data.text : ''
    if (data.kind === 'submit') {
      if (text.trim() !== '') await answer($, id, text, 'Answered in the pane')
    } else {
      await update($, drafts, old => ({ ...old, [id]: text }))
    }

    return {}
  })

  // A click on a pane that does not hold the keyboard only gives it the
  // keyboard: the desktop raises this focus move, naming the clicked element,
  // and no press (seen live, 2026-10-15). So when the pane was not focused and
  // the person's click lands on an action safe to run twice, run it here (D33).
  on('ui.focus', async ($, e, next) => {
    const wasFocused = isPaneFocused
    const result = await next(e)
    if (e.requestId !== PANE || e.origin.kind !== 'person' || e.element === undefined || wasFocused) return result
    const element = e.element
    const keep = keepFocusOn(element, (await readView($)).tab)
    if (keep !== undefined) await $.ui.focus({ requestId: PANE, key: keep }).catch(() => undefined)
    if (await runSafeAction($, element)) ranOnFocus = { element, at: await $.clock.now() }
    return result
  })

  // Before a press runs, the focus moves to something that outlasts it, so the
  // pane keeps the keyboard and the next click presses (hooks/focus.ts). A
  // press whose action already ran on the click that focused the pane is
  // dropped, so it does not run twice.
  on('ui.press', async ($, e, next) => {
    const ran = ranOnFocus
    ranOnFocus = undefined
    if (ran !== undefined && ran.element === e.element && (await $.clock.now()) - ran.at < 2000) {
      return { element: e.element }
    }
    const keep = keepFocusOn(e.element, (await readView($)).tab)
    if (keep !== undefined) await $.ui.focus({ requestId: e.requestId, key: keep }).catch(() => undefined)

    return next(e)
  })

  on('command.run', { command: 'questions' }, async ($, e) => {
    await $.ui.open({ id: PANE, title: TITLE })
    if (e.args.trim() === 'rebuild') {
      await rebuild($)
      return { text: 'Questions pane rebuilt from the conversation.' }
    }
    const live = (await read($, items)).filter(isLive).length

    return { text: `Questions pane opened: ${live} need you.` }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const table = $.ui.resolve(e)
    const { Box, Text, Button, Code } = table
    // The terminal and the desktop draw a Client, the multi-line editor, and
    // an Input; elsewhere an answer is an option or a default.
    const Client = 'Client' in table ? table.Client : undefined
    const Input = 'Input' in table ? table.Input : undefined
    const all = await read($, items)
    const v = await readView($)
    isPaneFocused = e.props.isFocused
    const needs = v.tab === 'needs'
    const shown = all.filter(i => (needs ? isLive(i) : !isLive(i)))
    const ready = queue(all)
    const setView = (fn: (old: PaneView) => PaneView) => update($, view, fn)
    // A card that needs you is open unless folded; a ready or answered card is
    // folded unless opened.
    const foldsByDefault = (i: Item) => !needs || i.status === 'ready'
    const isOpen = (i: Item) => (foldsByDefault(i) ? v.expanded.includes(i.id) : !v.collapsed.includes(i.id))
    const toggle = (i: Item) =>
      setView(old =>
        foldsByDefault(i)
          ? { ...old, expanded: toggled(old.expanded, i.id) }
          : { ...old, collapsed: toggled(old.collapsed, i.id) },
      )

    const pill = (i: Item): [string, string] => {
      if (i.status === 'answered') return [i.how === 'committed' ? 'Committed' : 'Sent', 'success']
      if (i.status === 'ready') return ['Ready', 'suggestion']
      if (i.status === 'looks') return ['Looks answered', 'warning']
      if (i.status === 'dismissed') return ['Dismissed', 'inactive']
      return ['Open', 'subtle']
    }
    const labelled = (label: string, value: string, color?: string) =>
      value === '' ? null : (
        <Box flexDirection="row" gap={1}>
          <Text dimColor={color === undefined} color={color} bold={color !== undefined}>
            {label}
          </Text>
          <Text>{value}</Text>
        </Box>
      )

    // Row 1 of every card: one Button of Texts, so pressing anywhere on it folds.
    const titleRow = (i: Item) => {
      const [word, color] = pill(i)
      return (
        <Button plain key={`card:${i.id}`} onPress={() => toggle(i)}>
          <Text inverse mono>{` ${i.code} `}</Text> <Text color={color} bold>
            {word}
          </Text>{' '}
          <Text bold>{i.title.replace(/`/g, '')}</Text> <Text dimColor>{`${KIND[i.kind]} ${isOpen(i) ? '▾' : '▸'}`}</Text>
        </Button>
      )
    }

    const contextLines = (i: Item) => (
      <Box flexDirection="column">
        {labelled('Why:', i.context)}
        {labelled('Stakes:', i.stakes)}
        {labelled('Driven by:', i.drivenBy)}
        {labelled('Blocks:', i.blocks)}
        {i.feeds.length > 0 && (
          <Box flexDirection="row" gap={1}>
            <Text dimColor>Feeds:</Text>
            {i.feeds.map(code => {
              const target = all.filter(x => x.code === code).sort((a, b) => b.at - a.at)[0]
              return (
                <Button
                  plain
                  key={`feeds:${i.id}:${code}`}
                  // Scrolling is a convenience: a refusal leaves the pane where it is.
                  onPress={() =>
                    target === undefined
                      ? undefined
                      : $.ui.scroll({ in: PANE, to: { key: `box:${target.id}` }, block: 'start' }).catch(() => undefined)
                  }
                >
                  <Text inverse mono>{` ${code} `}</Text>
                </Button>
              )
            })}
          </Box>
        )}
        {i.status !== 'ready' &&
          i.status !== 'looks' &&
          labelled(i.kind === 'decision' ? 'Recommended:' : 'Default:', i.recommendation)}
      </Box>
    )

    const editor = (i: Item, label: string) =>
      Client !== undefined ? (
        <Box flexDirection="column">
          <Text dimColor>{label}</Text>
          <Client key={`editor:${i.id}`} module="./editor.tsx" props={{ placeholder: 'Click here, then write your answer' }} />
        </Box>
      ) : Input !== undefined ? (
        <Input
          key={`answer:${i.id}`}
          label={label}
          placeholder="one line; Enter adds it"
          submitLabel="Add"
          onSubmit={text => answer($, i.id, text, 'Answered in the pane')}
        />
      ) : null

    const addDraft = (i: Item) => async () => {
      const draft = (await read($, drafts))[i.id]?.trim() ?? ''
      if (draft === '') {
        $.ui.toast('Write the answer first.')
        return
      }
      await answer($, i.id, draft, 'Answered in the pane')
    }
    const addButton = (i: Item) => (Client === undefined ? null : <Button key={`add:${i.id}`} label="Add" onPress={addDraft(i)} />)
    const dismissButton = (i: Item) => (
      <Button plain dimColor key={`dismiss:${i.id}`} label="Dismiss" onPress={() => runSafeAction($, `dismiss:${i.id}`)} />
    )

    const answerBlock = (i: Item) => {
      if (i.status === 'ready') {
        return (
          <Box flexDirection="column">
            {labelled('Your answer:', i.answer, 'suggestion')}
            <Box flexDirection="row" gap={1}>
              <Button key={`change:${i.id}`} label="Change" onPress={() => change($, (l, at) => toChange(l, i.id, at))} />
              <Button plain dimColor key={`undo:${i.id}`} label="Undo" onPress={() => change($, (l, at) => undone(l, i.id, at))} />
            </Box>
          </Box>
        )
      }
      if (i.status === 'looks') {
        return (
          <Box flexDirection="column">
            <Box flexDirection="row" gap={1}>
              <Text color="warning" bold>
                Your message:
              </Text>
              <Text italic>{`“${i.found}”`}</Text>
            </Box>
            <Box flexDirection="row" gap={1}>
              <Button variant="primary" key={`commit:${i.id}`} label="Commit" onPress={() => runSafeAction($, `commit:${i.id}`)} />
              <Button key={`cancel:${i.id}`} label="Cancel" onPress={() => runSafeAction($, `cancel:${i.id}`)} />
            </Box>
          </Box>
        )
      }
      if (i.kind === 'decision') {
        return (
          <Box flexDirection="column" gap={1}>
            {i.options.map((o, n) => (
              <Button
                key={`option:${i.id}:${n}`}
                variant={o.verdict === 'Recommended' ? 'primary' : undefined}
                onPress={() => runSafeAction($, `option:${i.id}:${n}`)}
              >
                <Text bold>{o.label}</Text> <Text dimColor>{`${o.verdict}: ${o.reason}`}</Text>
              </Button>
            ))}
            {editor(i, 'Or write your own:')}
            <Box flexDirection="row" gap={1}>
              {addButton(i)}
              {dismissButton(i)}
            </Box>
          </Box>
        )
      }
      if (i.kind === 'review') {
        const yes = approveWord(i)
        return (
          <Box flexDirection="column" gap={1}>
            <Box flexDirection="row" gap={1}>
              <Button variant="primary" key={`yes:${i.id}`} label={yes} onPress={() => runSafeAction($, `yes:${i.id}`)} />
              <Button key={`reverse:${i.id}`} label="Reverse" onPress={() => runSafeAction($, `reverse:${i.id}`)} />
            </Box>
            {editor(i, 'Or reply:')}
            <Box flexDirection="row" gap={1}>
              {addButton(i)}
              {dismissButton(i)}
            </Box>
          </Box>
        )
      }
      return (
        <Box flexDirection="column" gap={1}>
          {editor(i, 'Your answer:')}
          <Box flexDirection="row" gap={1}>
            {i.recommendation !== '' && (
              <Button
                variant="primary"
                key={`default:${i.id}`}
                label="Use default"
                onPress={() => runSafeAction($, `default:${i.id}`)}
              />
            )}
            {addButton(i)}
            {dismissButton(i)}
          </Box>
        </Box>
      )
    }

    const thread = (i: Item) =>
      i.thread.length === 0 && !v.asking.includes(i.id) ? null : (
        <Box flexDirection="column" marginLeft={1}>
          {i.thread.map(t => (
            <Box flexDirection="row" gap={1}>
              <Text bold color={t.who === 'fork' ? 'claude' : undefined}>
                {t.who === 'fork' ? 'Fork:' : 'You:'}
              </Text>
              <Text>{t.text}</Text>
            </Box>
          ))}
          {v.asking.includes(i.id) && (
            <Text dimColor italic>
              Fork: thinking…
            </Text>
          )}
        </Box>
      )

    // The Ask thread folds to its count; the field is drawn afresh after each
    // question (its key carries the thread's length), so it starts empty.
    const askBox = (i: Item) => {
      const isFolded = v.foldedThreads.includes(i.id)
      const asks = i.thread.filter(t => t.who === 'you').length
      return (
        <Box flexDirection="column">
          <Button plain key={`thread:${i.id}`} onPress={() => setView(old => ({ ...old, foldedThreads: toggled(old.foldedThreads, i.id) }))}>
            <Text dimColor bold>
              {asks === 0 ? 'Ask about this' : `Ask about this · ${asks} asked ${isFolded ? '▸' : '▾'}`}
            </Text>
          </Button>
          {!isFolded && thread(i)}
          {Input !== undefined && (
            <Input
              key={`ask:${i.id}:${i.thread.length}`}
              placeholder="what does this mean? why that default?"
              submitLabel="Ask"
              onSubmit={question => (v.asking.includes(i.id) ? undefined : askAbout($, i.id, question))}
            />
          )}
          <Text dimColor>Answered by a fork of this conversation. Nothing here reaches the main chat.</Text>
        </Box>
      )
    }

    const history = (i: Item) => (
      <Box flexDirection="column">
        <Text dimColor bold>
          History
        </Text>
        {i.history.map(entry => (
          <Box flexDirection="row" gap={2}>
            <Text dimColor>{clock(entry.at)}</Text>
            <Text>{entry.what}</Text>
          </Box>
        ))}
      </Box>
    )

    const answered = (i: Item) => (
      <Box flexDirection="column" gap={1}>
        {i.status === 'answered' ? labelled('Answer:', i.answer, 'success') : <Text dimColor>Dismissed without an answer</Text>}
        {i.options.map(o => (
          <Text dimColor={o.label !== i.answer}>{`${o.label === i.answer ? '✓' : ' '} ${o.label} · ${o.verdict}`}</Text>
        ))}
        {i.thread.length > 0 && (
          <Box flexDirection="column">
            <Text dimColor bold>
              Asked about it
            </Text>
            {thread(i)}
          </Box>
        )}
        {history(i)}
        <Box flexDirection="row">
          <Button key={`reopen:${i.id}`} label="Reopen" onPress={() => change($, (l, at) => reopened(l, i.id, at))} />
        </Box>
      </Box>
    )

    const card = (i: Item) => (
      <Box key={`box:${i.id}`} flexDirection="column" borderStyle="round" paddingX={1}>
        {titleRow(i)}
        {!isOpen(i) && (i.status === 'ready' || !needs) && (
          <Box marginLeft={2}>
            <Text dimColor wrap="truncate-end">
              {i.status === 'dismissed' ? 'Dismissed without an answer' : `Your answer: ${i.answer}`}
            </Text>
          </Box>
        )}
        {isOpen(i) && (
          <Box flexDirection="column" marginLeft={2} gap={1}>
            {contextLines(i)}
            {needs ? answerBlock(i) : answered(i)}
            {needs && i.status !== 'ready' && askBox(i)}
          </Box>
        )}
      </Box>
    )

    // One list in the order the questions were asked: oldest turn first, a
    // turn's items in the reply's order (the sort is stable).
    const ordered = [...shown].sort((a, b) => a.at - b.at)
    const defaults = needs ? shown.filter(canDefault) : []

    const tabButton = (tab: PaneView['tab'], label: string) => (
      <Button plain key={`tab:${tab}`} onPress={() => setView(old => ({ ...old, tab }))}>
        <Text bold={v.tab === tab} underline={v.tab === tab} dimColor={v.tab !== tab}>
          {label}
        </Text>
      </Button>
    )

    return (
      <Box flexDirection="column" gap={1}>
        <Box flexDirection="row" gap={2} flexWrap="wrap">
          {tabButton('needs', `Needs you · ${all.filter(isLive).length}`)}
          {tabButton('answered', `Answered · ${all.filter(i => !isLive(i)).length}`)}
          <Button
            key="rebuild"
            dimColor={v.rebuild !== ''}
            label={v.rebuild === '' ? 'Rebuild from the conversation' : 'Rebuilding…'}
            onPress={() => runSafeAction($, 'rebuild')}
          />
        </Box>
        {v.rebuild !== '' && (
          <Text color="suggestion" bold>{`⟳ ${v.rebuild}`}</Text>
        )}
        {needs && (
          <Box flexDirection="column">
            <Box flexDirection="row" gap={1} flexWrap="wrap">
              <Text dimColor>{`${ready.length} ready to send`}</Text>
              {defaults.length > 0 && (
                <Button
                  key="defaults"
                  label={`Use all defaults · ${defaults.length}`}
                  onPress={() =>
                    change($, (l, at) => readied(l, new Map(defaults.map(d => [d.id, defaultAnswer(d)])), 'Default taken in the pane', at))
                  }
                />
              )}
              <Button
                plain
                dimColor
                key="preview"
                label={v.preview ? 'Hide preview' : 'Preview'}
                onPress={() => setView(old => ({ ...old, preview: !old.preview }))}
              />
              <Button
                variant="primary"
                dimColor={ready.length === 0}
                key="send"
                label={`Send ${ready.length}`}
                onPress={() => (ready.length === 0 ? $.ui.toast('Nothing is ready. Answer a question first.') : send($))}
              />
            </Box>
            {v.preview && ready.length > 0 && <Code source={ready.map(lineFor).join('\n')} />}
          </Box>
        )}
        {shown.length === 0 && (
          <Text dimColor>
            {needs ? 'Nothing needs you. New questions appear here when an agent asks them.' : 'Nothing answered yet.'}
          </Text>
        )}
        {ordered.map(card)}
      </Box>
    )
  })
}

