// The list's changes, as plain functions over it: answering in the pane, the
// message Send puts in the prompt box, what a submitted prompt says about the
// list, and every change written into the item's history.

import type { HistoryEntry, Item, ItemOption, ItemStatus, Parsed, ThreadEntry } from '../types'
import { answeredCodes } from './parse'

export const isLive = (i: Item) => i.status === 'open' || i.status === 'ready' || i.status === 'looks'

// Only an item with a default or recommendation can take it.
export const canDefault = (i: Item) => i.recommendation !== '' && (i.status === 'open' || i.status === 'looks')

export function defaultAnswer(i: Item): string {
  return `${i.kind === 'decision' ? 'your recommendation' : 'your default'}, ${i.recommendation}`
}

// The message's text for one item: its code and title, so the agent cannot
// confuse two items that share a code, then the answer, which may run to
// several lines.
export function lineFor(i: Item): string {
  return `${i.code} (${i.title.replace(/`/g, '')}): ${i.answer}`
}

function changed(i: Item, change: Partial<Item>, what: string, at: number): Item {
  return { ...i, ...change, history: [...i.history, { at, what }] }
}

function each(list: readonly Item[], ids: ReadonlySet<string>, fn: (i: Item) => Item): Item[] {
  return list.map(i => (ids.has(i.id) ? fn(i) : i))
}

export function added(
  list: readonly Item[],
  parsed: readonly Parsed[],
  turnId: string,
  topic: string,
  at: number,
): Item[] {
  const known = new Set(list.map(i => i.id))
  const fresh: Item[] = parsed
    .map(p => ({
      ...p,
      id: `${turnId}:${p.code}`,
      turnId,
      topic,
      at,
      status: 'open' as const,
      answer: '',
      how: '' as const,
      found: '',
      thread: [],
      history: [{ at, what: 'Asked' }],
    }))
    .filter(i => !known.has(i.id))

  return [...list, ...fresh]
}

// Answered in the pane: ready to send.
export function readied(list: readonly Item[], answers: ReadonlyMap<string, string>, what: string, at: number): Item[] {
  return list.map(i => {
    const answer = answers.get(i.id)?.trim()

    return answer === undefined || answer === '' ? i : changed(i, { status: 'ready', answer, found: '' }, what, at)
  })
}

export function undone(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i => changed(i, { status: 'open', answer: '' }, 'Answer undone', at))
}

export function toChange(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i => changed(i, { status: 'open' }, 'Reopened to change the answer', at))
}

export function committed(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i =>
    changed(i, { status: 'answered', how: 'committed', answer: i.found }, 'Committed', at),
  )
}

export function cancelled(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i => changed(i, { status: 'open', found: '' }, 'Not an answer: back to open', at))
}

export function dismissed(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i => changed(i, { status: 'dismissed' }, 'Dismissed', at))
}

export function reopened(list: readonly Item[], id: string, at: number): Item[] {
  return each(list, new Set([id]), i => changed(i, { status: 'open', answer: '', how: '', found: '' }, 'Reopened', at))
}

export function sent(list: readonly Item[], ids: ReadonlySet<string>, at: number): Item[] {
  return each(list, ids, i => changed(i, { status: 'answered', how: 'sent' }, 'Sent', at))
}

// Things the person wrote that look like answers: commit or cancel each.
export function looked(list: readonly Item[], found: ReadonlyMap<string, string>, at: number): Item[] {
  return list.map(i => {
    const quote = found.get(i.id)

    return quote === undefined || (i.status !== 'open' && i.status !== 'ready')
      ? i
      : changed(i, { status: 'looks', found: quote }, 'Your message looks like an answer', at)
  })
}

export function asked(list: readonly Item[], id: string, entry: ThreadEntry): Item[] {
  return each(list, new Set([id]), i => ({
    ...i,
    thread: [...i.thread, entry],
    history: entry.who === 'you' ? [...i.history, { at: entry.at, what: 'Asked about it in the pane' }] : i.history,
  }))
}

// The ready items in the order they were asked: oldest turn first, a turn's
// items in the reply's order.
export function queue(list: readonly Item[]): Item[] {
  return list.filter(i => i.status === 'ready').sort((a, b) => a.at - b.at)
}

export function message(list: readonly Item[]): string {
  return queue(list).map(lineFor).join('\n')
}

// The newest item under a code with one of the statuses.
export function newest(list: readonly Item[], code: string, statuses: readonly ItemStatus[]): Item | undefined {
  return list
    .filter(i => i.code === code && statuses.includes(i.status))
    .reduce<Item | undefined>((best, i) => (best === undefined || i.at >= best.at ? i : best), undefined)
}

// What a prompt the person submitted says, without a model: a ready item
// whose text it holds unchanged is sent; a line that starts with a code
// looks like an answer to the newest open or ready item under it.
export function submitted(list: readonly Item[], text: string, at: number): Item[] {
  const wasSent = new Set(list.filter(i => i.status === 'ready' && text.includes(lineFor(i))).map(i => i.id))
  const after = sent(list, wasSent, at)
  const found = new Map<string, string>()
  for (const line of text.split('\n')) {
    const [code] = answeredCodes(line)
    if (code === undefined) continue
    const hit = newest(after, code, ['open', 'ready'])
    if (hit !== undefined && !found.has(hit.id)) found.set(hit.id, line.trim())
  }

  return looked(after, found, at)
}

const STATUSES: readonly ItemStatus[] = ['open', 'ready', 'looks', 'answered', 'dismissed']

function isOption(o: unknown): o is ItemOption {
  return (
    typeof o === 'object' &&
    o !== null &&
    'label' in o &&
    typeof o.label === 'string' &&
    'verdict' in o &&
    typeof o.verdict === 'string' &&
    'reason' in o &&
    typeof o.reason === 'string'
  )
}

function isHistoryEntry(h: unknown): h is HistoryEntry {
  return typeof h === 'object' && h !== null && 'at' in h && typeof h.at === 'number' && 'what' in h && typeof h.what === 'string'
}

function isThreadEntry(t: unknown): t is ThreadEntry {
  return (
    typeof t === 'object' &&
    t !== null &&
    'who' in t &&
    (t.who === 'you' || t.who === 'fork') &&
    'text' in t &&
    typeof t.text === 'string' &&
    'at' in t &&
    typeof t.at === 'number'
  )
}

const str = (v: unknown) => (typeof v === 'string' ? v : '')

// A list this mod saved, read back: undefined when it is not one. A field an
// older version did not save is filled with its empty value; an older
// version's statuses are read as today's (queued is ready, maybe is looks).
export function restored(value: unknown): Item[] | undefined {
  if (!Array.isArray(value)) return undefined
  const rows: unknown[] = value
  const out: Item[] = []
  for (const raw of rows) {
    if (typeof raw !== 'object' || raw === null) return undefined
    const i: Record<string, unknown> = { ...raw }
    const legacy = i.status === 'queued' ? 'ready' : i.status === 'maybe' ? 'looks' : i.status
    const status = STATUSES.find(s => s === legacy)
    if (
      typeof i.id !== 'string' ||
      typeof i.code !== 'string' ||
      typeof i.title !== 'string' ||
      typeof i.turnId !== 'string' ||
      typeof i.at !== 'number' ||
      status === undefined ||
      (i.kind !== 'question' && i.kind !== 'decision' && i.kind !== 'review')
    ) {
      return undefined
    }
    const list = (v: unknown): unknown[] => (Array.isArray(v) ? v : [])
    out.push({
      id: i.id,
      code: i.code,
      kind: i.kind,
      title: i.title,
      body: str(i.body),
      recommendation: str(i.recommendation),
      options: list(i.options).filter(isOption),
      context: str(i.context),
      stakes: str(i.stakes),
      drivenBy: str(i.drivenBy),
      blocks: str(i.blocks),
      feeds: list(i.feeds).filter((f): f is string => typeof f === 'string'),
      source: str(i.source),
      parsedBy: i.parsedBy === 'haiku' ? 'haiku' : 'regex',
      turnId: i.turnId,
      topic: str(i.topic),
      at: i.at,
      status,
      answer: str(i.answer),
      how: i.how === 'sent' || i.how === 'committed' ? i.how : '',
      found: str(i.found),
      thread: list(i.thread).filter(isThreadEntry),
      history: list(i.history).filter(isHistoryEntry),
    })
  }

  return out
}

export type AfterFill = 'filled' | 'submit' | 'dialog' | 'kept'

// What Send does after the prompt box answered: done when the box took the
// text; submit as the person's words when the engine said the session has
// no box; otherwise keep the answers ready. Only the engine's own refusal
// names a cause: a hook's carries none, and an absent cause is unknown.
export function afterFill(filled: { isFilled: boolean; refusal?: 'no_composer' | 'dialog' }): AfterFill {
  if (filled.isFilled) return 'filled'
  if (filled.refusal === 'no_composer') return 'submit'

  return filled.refusal === 'dialog' ? 'dialog' : 'kept'
}

files.hooks/ask.ts:
// What "Ask about this" sends to a fork of the conversation. A fork always
// starts from the conversation as it is now (ModelForkRequest takes only the
// prompt), so the prompt names which question, which round, and when it was
// asked; the fork sees what was said since then too.

import type { Item } from '../types'

export function askPrompt(i: Item, question: string, asked: string): string {
  const lines = [
    'The person is asking you about one of the questions you put to them. Explain; do not answer the question for them, and do not start any work.',
    'Answer in plain words, in at most a few short paragraphs. This answer stays in their question pane: it is not part of the conversation and is not their answer.',
    '',
    `The question: ${i.code} (${i.kind}), asked at ${asked}${i.topic === '' ? '' : `, in the round about: ${i.topic}`}`,
    `"${i.title}"`,
  ]
  if (i.context !== '') lines.push(`Why it was asked: ${i.context}`)
  if (i.recommendation !== '') lines.push(`Your ${i.kind === 'decision' ? 'recommendation' : 'default'}: ${i.recommendation}`)
  for (const o of i.options) lines.push(`Option ${o.label}: ${o.verdict}: ${o.reason}`)
  const earlier = i.thread.filter(t => t.text !== '')
  if (earlier.length > 0) {
    lines.push('', 'What they asked about it before, and your answers:')
    for (const t of earlier) lines.push(`${t.who === 'you' ? 'They asked' : 'You answered'}: ${t.text}`)
  }
  lines.push('', `Their question now: ${question}`)

  return lines.join('\n')
}

files.hooks/focus.ts:
// Where the pane's keyboard focus goes before a press runs. On the desktop,
// a press that removes the pressed button (Use default folds the card; Commit
// and Dismiss move it off the tab) takes the pane's focus with it, and the
// next click is then spent giving the pane focus back, so it presses nothing
// (seen live, 2026-10-15: a `focused=false` drawing followed each such press,
// and the next click raised `ui.focus` but no `ui.press`). Moving the focus
// first to something that stays keeps the pane focused.

// The key to move the focus to before pressing `element`, or undefined to
// leave it: the card's title row when the card stays on the tab, the tab's own
// button when the card leaves it.
export function keepFocusOn(element: string, tab: 'needs' | 'answered'): string | undefined {
  const [action, turnId, code] = element.split(':')
  if (action === undefined || turnId === undefined || code === undefined) return undefined
  const card = `card:${turnId}:${code}`
  switch (action) {
    // The card stays on Needs you, folded or reopened.
    case 'default':
    case 'option':
    case 'add':
    case 'yes':
    case 'reverse':
    case 'change':
    case 'undo':
    case 'cancel':
      return card
    // The card leaves the tab it is on.
    case 'commit':
    case 'dismiss':
    case 'reopen':
      return `tab:${tab}`
    default:
      return undefined
  }
}

files.hooks/haiku.ts:
// Haiku turns a reply into items; this file asks it and checks what it says.
// A completion has no structured-output mode (ModelCompleteRequest takes
// model, prompt, system, maxTokens, effort, timeoutMs), so the checks here
// are what hold Haiku to the reply: an item's text must be in the reply, in
// that item's own block where the regex found one, and a field that is not
// falls back to the regex's.

import type { ItemKind, ItemOption, Parsed } from '../types'
import { norm, parseRegex, stripFences, topicOf } from './parse'

export const RULES = `You turn one message an AI agent wrote to a person into JSON: the items it puts to that person, and what the message is about.

An item is one of:
- "question": a numbered question, Q1, Q2, ...: either a line "❓ **Q1** - **title**: body" followed by "➡️ recommended answer", or a line "- Q1: question Default: default answer" under "❓ **Questions:**".
- "decision": a heading "🫵 D1: question" with "**Recommendation:**", "**Stakes:**", "**Driven by:**", maybe "**Blocks:**", and a list of options, each "(a) option" with "**Recommended:**", "**Not recommended:**" or "**Rejected:**" and a reason.
- "review": under "🔍 **Review:**", an entry "D2, pending: ..." or "D2, taken: ...".

Ignore anything inside code fences: those are examples, not items.

Copy text exactly as the message writes it, without its markdown marks. Never reword, never summarize, never add an item the message does not number.

Answer with JSON alone, no prose and no code fence:
{"topic":"...","items":[{"code":"Q1","kind":"question","title":"...","body":"...","recommendation":"...","context":"...","stakes":"...","drivenBy":"...","blocks":"...","feeds":["D1"],"options":[{"label":"(a) ...","verdict":"Recommended","reason":"..."}]}]}

"topic" is the one sentence of the message that best says what this round of questions is about.
"title" is the item's question or call in one line. "body" is the rest of the item's own text.
"recommendation" is its recommended or default answer.
"context" is the sentences elsewhere in the message that explain why this item is asked: copied, at most three sentences.
"stakes", "drivenBy" and "blocks" are a decision's labelled lines.
"feeds" lists the codes the item says it feeds ("Feeds D1").
Use "" for a text the message does not have, [] for a list. "options" is [] unless it is a decision.`

const KINDS: readonly ItemKind[] = ['question', 'decision', 'review']

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : ''
}

// What Haiku answered, as JSON: the outermost object in its text.
export function readJson(answer: string): unknown {
  const start = answer.indexOf('{')
  const end = answer.lastIndexOf('}')
  if (start === -1 || end <= start) return undefined
  try {
    return JSON.parse(answer.slice(start, end + 1))
  } catch {
    return undefined
  }
}

function holds(where: string, part: string): boolean {
  return part === '' || where.includes(norm(part))
}

export type HaikuAnswer = { topic: string; items: Parsed[] }

// Haiku's answer, each item and field held to the reply; undefined when the
// answer is not the JSON asked for, so the caller can ask once more. An item
// the regex also found is held to that item's own block, so a title or
// recommendation moved from a neighbouring item is refused; its context may
// come from anywhere in the reply. A context, stakes, drivenBy or blocks the
// reply does not hold is dropped, the item kept.
export function checkHaiku(
  answer: string,
  reply: string,
  blocks: ReadonlyMap<string, string> = new Map(),
): HaikuAnswer | undefined {
  const json = readJson(answer)
  if (!isRecord(json) || !Array.isArray(json.items)) return undefined
  const whole = norm(stripFences(reply))
  const topic = holds(whole, text(json.topic)) ? text(json.topic) : ''
  const items: Parsed[] = []
  for (const raw of json.items) {
    if (!isRecord(raw)) continue
    const code = text(raw.code).toUpperCase()
    const kind = KINDS.find(k => k === raw.kind)
    const block = blocks.get(code)
    const own = block === undefined ? whole : norm(block)
    const title = text(raw.title)
    const body = text(raw.body)
    const recommendation = text(raw.recommendation)
    const options: ItemOption[] = (Array.isArray(raw.options) ? raw.options : [])
      .filter(isRecord)
      .map(o => ({ label: text(o.label), verdict: text(o.verdict), reason: text(o.reason) }))
    const isBacked =
      /^[QD]\d+$/.test(code) &&
      kind !== undefined &&
      title !== '' &&
      new RegExp(`\\b${code}\\b`, 'i').test(whole) &&
      holds(own, title) &&
      holds(own, body) &&
      holds(own, recommendation) &&
      options.every(o => holds(own, o.label))
    if (!isBacked || kind === undefined) continue
    const kept = (value: unknown, where: string) => (holds(where, text(value)) ? text(value) : '')
    const feeds = (Array.isArray(raw.feeds) ? raw.feeds : [])
      .map(text)
      .map(f => f.toUpperCase())
      .filter(f => /^[QD]\d+$/.test(f) && new RegExp(`\\b${f}\\b`, 'i').test(own))
    items.push({
      code,
      kind,
      title,
      body,
      recommendation,
      options,
      context: kept(raw.context, whole),
      stakes: kept(raw.stakes, own),
      drivenBy: kept(raw.drivenBy, own),
      blocks: kept(raw.blocks, own),
      feeds,
      source: '',
      parsedBy: 'haiku',
    })
  }

  return { topic, items }
}

// A field Haiku left empty takes the regex's.
function filled(h: Parsed, r: Parsed): Parsed {
  return {
    ...h,
    body: h.body || r.body,
    recommendation: h.recommendation || r.recommendation,
    options: h.options.length > 0 ? h.options : r.options,
    stakes: h.stakes || r.stakes,
    drivenBy: h.drivenBy || r.drivenBy,
    blocks: h.blocks || r.blocks,
    feeds: h.feeds.length > 0 ? h.feeds : r.feeds,
    source: r.source,
  }
}

// One list: each code once, in the reply's order. Haiku's item where the
// reply backs it, the regex item otherwise, and every code the regex found
// that Haiku missed. The source text is always the regex's, where it has one.
export function merge(fromRegex: readonly Parsed[], fromHaiku: readonly Parsed[]): Parsed[] {
  const byCode = new Map(fromHaiku.map(p => [p.code, p]))
  const out: Parsed[] = fromRegex.map(r => {
    const h = byCode.get(r.code)
    byCode.delete(r.code)

    return h === undefined ? r : filled(h, r)
  })
  for (const h of byCode.values()) out.push({ ...h, source: h.title })

  return out
}

export type Ask = (system: string, prompt: string) => Promise<string | undefined>

// The reply's items and topic: the regex pass, then Haiku asked up to twice
// for an answer that is the JSON asked for; the regex items alone, and the
// reply's first line as the topic, when it never is.
export async function parseReply(reply: string, ask: Ask): Promise<HaikuAnswer> {
  const fromRegex = parseRegex(reply)
  for (let attempt = 0; attempt < 2; attempt += 1) {
    const answer = await ask(RULES, reply)
    if (answer === undefined) break
    const fromHaiku = checkHaiku(answer, reply, new Map(fromRegex.map(r => [r.code, r.source])))
    if (fromHaiku !== undefined) {
      return { topic: fromHaiku.topic || topicOf(reply), items: merge(fromRegex, fromHaiku.items) }
    }
  }

  return { topic: topicOf(reply), items: fromRegex }
}

