// Whether something the person wrote answers questions still open: Haiku
// reads the message beside the open items and names each one it answers,
// with a quote. A quote the message does not hold is refused, so Haiku can
// only point at the person's own words, never put words in their mouth.

import type { Item } from '../types'
import { readJson } from './haiku'
import { norm } from './parse'

export const LOOKS_RULES = `A person is answering questions an AI agent asked them. You get the questions still open and the message the person just wrote.

Name each open question the message answers, plainly or in passing. For each, copy the exact words of the message that answer it.

Only name a question the message really answers. A message that only asks about a question, or mentions its topic, does not answer it.

Answer with JSON alone, no prose and no code fence:
{"answered":[{"code":"Q3","quote":"the exact words from the message"}]}

Answer {"answered":[]} when the message answers none.`

export function looksPrompt(open: readonly Item[], text: string): string {
  const questions = open
    .map(i => `${i.code}: ${i.title}${i.recommendation === '' ? '' : ` (default: ${i.recommendation})`}`)
    .join('\n')

  return `Open questions:\n${questions}\n\nThe person's message:\n${text}`
}

// The items Haiku says the message answers, each with its quote; an unknown
// code, a closed item or a quote not in the message is dropped. A code shared
// by two open items names the newest.
export function checkLooks(answer: string, text: string, open: readonly Item[]): Map<string, string> {
  const out = new Map<string, string>()
  const json = readJson(answer)
  if (typeof json !== 'object' || json === null || !('answered' in json) || !Array.isArray(json.answered)) return out
  const said = norm(text)
  const rows: unknown[] = json.answered
  for (const row of rows) {
    if (typeof row !== 'object' || row === null || !('code' in row) || !('quote' in row)) continue
    const code = typeof row.code === 'string' ? row.code.trim().toUpperCase() : ''
    const quote = typeof row.quote === 'string' ? row.quote.trim() : ''
    if (quote === '' || !said.includes(norm(quote))) continue
    const hit = open
      .filter(i => i.code === code)
      .reduce<Item | undefined>((best, i) => (best === undefined || i.at >= best.at ? i : best), undefined)
    if (hit !== undefined && !out.has(hit.id)) out.set(hit.id, quote)
  }

  return out
}

