// Finds the items an agent puts to the person in one reply, by the four
// formats they are written in:
//   grilling:            ❓ **Q1** - **<title>**: <body>  then  ➡️ <recommendation>
//   output style Q:      ❓ **Questions:**  then  - Q1: <question> Default: <default>. Feeds D1.
//   output style D:      ### 🫵 D1: <question>  then  **Recommendation:** <...>
//   output style Review: 🔍 **Review:** D2, pending: <call>  (or taken:)
// Text inside code fences is an example, never an item.

import type { ItemKind, ItemOption, Parsed } from '../types'

const FENCE = /^(`{3,}|~{3,})[^\n]*\n[\s\S]*?^\1[ \t]*$/gm

export function stripFences(text: string): string {
  return text.replace(FENCE, '')
}

export function hasMarker(text: string): boolean {
  const plain = stripFences(text)

  return /❓|🫵|🔍/u.test(plain) || /^\s*[-*]\s*Q\d+:/m.test(plain)
}

// Lowercased, markdown marks and spacing dropped: what "found in the reply"
// compares, so a title Haiku copied without its bold still matches.
export function norm(text: string): string {
  return text
    .replace(/[*_`>#]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()
}

type Found = Parsed & { at: number }

// A line where an item's block ends.
const ITEM_END = /^(?:#{1,6}\s|❓|🔍|🫵|➡️\s*\*\*Next|---\s*$)/mu
// A decision's block keeps its own `#### Options` subheading.
const DECISION_END = /^(?:#{1,3}\s|❓|🔍|➡️\s*\*\*Next|---\s*$)/mu

function blockAfter(text: string, from: number, end: RegExp): string {
  const rest = text.slice(from)
  const hit = end.exec(rest)

  return hit === null ? rest : rest.slice(0, hit.index)
}

function item(
  at: number,
  code: string,
  kind: ItemKind,
  fields: Partial<Omit<Parsed, 'code' | 'kind' | 'parsedBy'>>,
): Found {
  return {
    at,
    code,
    kind,
    title: (fields.title ?? '').trim(),
    body: (fields.body ?? '').trim(),
    recommendation: (fields.recommendation ?? '').trim(),
    options: fields.options ?? [],
    context: (fields.context ?? '').trim(),
    stakes: (fields.stakes ?? '').trim(),
    drivenBy: (fields.drivenBy ?? '').trim(),
    blocks: (fields.blocks ?? '').trim(),
    feeds: fields.feeds ?? [],
    source: (fields.source ?? '').trim(),
    parsedBy: 'regex',
  }
}

// The codes a "Feeds D1, D2" clause names.
function feedsIn(text: string): string[] {
  const clause = /Feeds\s+((?:D\d+)(?:\s*(?:,|and)\s*D\d+)*)/.exec(text)?.[1] ?? ''

  return [...clause.matchAll(/D\d+/g)].map(m => m[0])
}

// A decision card's labelled line: `**Stakes:** <text>`.
function labelled(block: string, label: string): string {
  return new RegExp(`\\*\\*${label}:\\*\\*[ \\t]*([^\\n]+)`).exec(block)?.[1]?.trim() ?? ''
}

const GRILL = /^❓\s*\*\*Q(\d+)\*\*\s*[-–:]\s*\*\*(.+?)\*\*\s*:?[ \t]*(.*)$/gmu

function grilling(text: string): Found[] {
  const found: Found[] = []
  for (const m of text.matchAll(GRILL)) {
    const start = m.index ?? 0
    const lineEnd = start + m[0].length
    const tail = blockAfter(text, lineEnd + 1, ITEM_END)
    const arrow = tail.search(/^➡️/mu)
    const body = [m[3] ?? '', arrow === -1 ? tail : tail.slice(0, arrow)].join('\n')
    const recommendation = arrow === -1 ? '' : tail.slice(arrow).replace(/^➡️\s*/u, '')
    found.push(
      item(start, `Q${m[1]}`, 'question', {
        title: m[2],
        body,
        recommendation,
        source: text.slice(start, lineEnd + 1 + tail.length),
      }),
    )
  }

  return found
}

const QUESTION_LINE = /^[ \t]*[-*][ \t]*Q(\d+):[ \t]*(.+)$/gm

function questionLines(text: string): Found[] {
  if (!/\*\*Questions:\*\*/.test(text)) return []
  const found: Found[] = []
  for (const m of text.matchAll(QUESTION_LINE)) {
    const line = (m[2] ?? '').trim()
    const split = line.search(/\s+Default:\s*/)
    const title = split === -1 ? line : line.slice(0, split)
    const recommendation =
      split === -1
        ? ''
        : line
            .slice(split)
            .replace(/^\s+Default:\s*/, '')
            .replace(/\s*Feeds\s+D\d+(?:\s*(?:,|and)\s*D\d+)*\.?\s*$/, '')
    found.push(
      item(m.index ?? 0, `Q${m[1]}`, 'question', {
        title,
        recommendation,
        feeds: feedsIn(line),
        source: m[0],
      }),
    )
  }

  return found
}

const DECISION = /^#{1,6}[ \t]*🫵[ \t]*D(\d+):[ \t]*(.+)$/gmu
const OPTION = /^[ \t]*[-*][ \t]*(\([a-z]\)[^\n]*)\n[ \t]*\*\*(Recommended|Not recommended|Rejected):\*\*[ \t]*([^\n]*)/gm

function decisions(text: string): Found[] {
  const found: Found[] = []
  for (const m of text.matchAll(DECISION)) {
    const start = m.index ?? 0
    const lineEnd = start + m[0].length
    const tail = blockAfter(text, lineEnd + 1, DECISION_END)
    const recommendation = labelled(tail, 'Recommendation')
    const options: ItemOption[] = [...tail.matchAll(OPTION)].map(o => ({
      label: (o[1] ?? '').trim(),
      verdict: o[2] ?? '',
      reason: (o[3] ?? '').trim(),
    }))
    found.push(
      item(start, `D${m[1]}`, 'decision', {
        title: m[2],
        recommendation,
        stakes: labelled(tail, 'Stakes'),
        drivenBy: labelled(tail, 'Driven by'),
        blocks: labelled(tail, 'Blocks'),
        options,
        source: text.slice(start, lineEnd + 1 + tail.length),
      }),
    )
  }

  return found
}

const REVIEW = /🔍\s*\*\*Review:\*\*/gu
const REVIEW_ITEM = /\bD(\d+),[ \t]*(pending|taken):[ \t]*([^\n]+)/g

function reviews(text: string): Found[] {
  const found: Found[] = []
  for (const m of text.matchAll(REVIEW)) {
    const start = m.index ?? 0
    const from = start + m[0].length
    const segment = blockAfter(text, from, /^(?:#{1,6}\s|❓|🫵|➡️\s*\*\*Next|---\s*$)/mu)
    for (const r of segment.matchAll(REVIEW_ITEM)) {
      const line = (r[3] ?? '').trim()
      found.push(
        item(from + (r.index ?? 0), `D${r[1]}`, 'review', {
          title: `${r[2]}: ${line}`,
          source: r[0],
        }),
      )
    }
  }

  return found
}

// Every item the four formats find, in the order the reply has them; a code
// found twice keeps its first.
export function parseRegex(reply: string): Parsed[] {
  const text = stripFences(reply)
  const all = [...grilling(text), ...questionLines(text), ...decisions(text), ...reviews(text)]
  all.sort((a, b) => a.at - b.at)
  const seen = new Set<string>()
  const out: Parsed[] = []
  for (const { at: _at, ...found } of all) {
    if (seen.has(found.code)) continue
    seen.add(found.code)
    out.push(found)
  }

  return out
}

// The codes a line of the person's prompt starts with: `Q7`, `D1`, `**Q3**`,
// `- D2:`. A bare number names nothing.
export function answeredCodes(prompt: string): string[] {
  const codes = new Set<string>()
  for (const m of prompt.matchAll(/^[ \t]*(?:[-*][ \t]*)?\**([QD]\d+)\b/gim)) {
    codes.add((m[1] ?? '').toUpperCase())
  }

  return [...codes]
}

// What a round is about, for its header: the reply's first line that is not
// an item, its markdown marks dropped, cut to one line.
export function topicOf(reply: string): string {
  const lines = stripFences(reply)
    .split('\n')
    .map(l => l.replace(/[*_`#>]/g, '').replace(/^[^\p{L}\p{N}]+/u, '').replace(/^Orientation:\s*/i, '').trim())
    .filter(l => l !== '' && !/^(?:Q|D)\d+\b/.test(l) && !/^Questions:?$/.test(l))
  const first = lines[0] ?? ''

  return first.length > 120 ? `${first.slice(0, 117)}...` : first
}

files.hooks/rebuild.ts:
// "Rebuild from the conversation": the items of the agent's recent replies,
// parsed again, merged into the list. A reply's items that the list already
// holds (same code, same title) are refreshed in place and keep their status,
// answer, thread and history; the rest are added. A reply in the transcript
// carries no turn id or time, so an added item's id comes from the reply's
// place among the replies read, and its time puts it before every item the
// list already holds, in the order the replies came: most rebuilt items were
// asked before the mod was tracking.

import type { Item, Parsed } from '../types'
import { norm } from './parse'

export type RebuiltReply = {
  // Its place among the replies read, 0 the oldest.
  index: number
  topic: string
  items: readonly Parsed[]
  // What the person wrote after it, before the agent's next reply with items.
  after: string
}

// The replies to parse: each assistant message with text, with the person's
// messages that followed it, the newest `limit` of them.
export function repliesIn(
  messages: readonly { role: 'user' | 'assistant'; text: string }[],
  isItemReply: (text: string) => boolean,
  limit: number,
): { text: string; after: string }[] {
  const out: { text: string; after: string }[] = []
  for (const m of messages) {
    if (m.role === 'assistant' && isItemReply(m.text)) out.push({ text: m.text, after: '' })
    else if (m.role === 'user' && out.length > 0) {
      const last = out[out.length - 1]
      if (last !== undefined) last.after = last.after === '' ? m.text : `${last.after}\n\n${m.text}`
    }
  }

  return out.slice(-limit)
}

const sameItem = (a: Pick<Parsed, 'code' | 'title'>, b: Pick<Parsed, 'code' | 'title'>) =>
  a.code === b.code && norm(a.title) === norm(b.title)

export function rebuilt(
  list: readonly Item[],
  replies: readonly RebuiltReply[],
  now: number,
): { list: Item[]; added: number; refreshed: number } {
  let out = [...list]
  let added = 0
  let refreshed = 0
  const count = replies.length
  const base = Math.min(now, ...list.map(i => i.at))
  for (const reply of replies) {
    for (const p of reply.items) {
      const known = out.find(i => sameItem(i, p))
      if (known !== undefined) {
        out = out.map(i =>
          i.id === known.id
            ? {
                ...i,
                body: p.body || i.body,
                recommendation: p.recommendation || i.recommendation,
                options: p.options.length > 0 ? p.options : i.options,
                context: p.context || i.context,
                stakes: p.stakes || i.stakes,
                drivenBy: p.drivenBy || i.drivenBy,
                blocks: p.blocks || i.blocks,
                feeds: p.feeds.length > 0 ? p.feeds : i.feeds,
                source: p.source || i.source,
                topic: i.topic || reply.topic,
              }
            : i,
        )
        refreshed += 1
        continue
      }
      const turnId = `rebuilt-${reply.index}`
      out.push({
        ...p,
        id: `${turnId}:${p.code}`,
        turnId,
        topic: reply.topic,
        at: base - (count - reply.index) * 1000,
        status: 'open',
        answer: '',
        how: '',
        found: '',
        thread: [],
        history: [{ at: now, what: 'Found when rebuilding from the conversation' }],
      })
      added += 1
    }
  }

  return { list: out, added, refreshed }
}

files.hooks/editor.tsx:
// A multi-line answer editor: a Client region the pane draws inside a card,
// since the pane's own Input is one line (Enter submits it). It takes keys
// once a click gives it the focus: Enter is a new line, Ctrl+Enter (or
// Cmd+Enter) adds the answer. Each change is posted to the hooks module, which
// keeps it as the item's draft so the card's Add button can add it too.
// A key whose name is longer than one character and is not a special key is
// inserted as text, which is how a paste would arrive if it arrives as one
// key; whether a paste reaches a Client at all is not yet known.

import type { ClientKeyEvent, ClientModule } from 'claude-code'

export type EditorProps = { placeholder: string }
export type EditorPost = { kind: 'change' | 'submit'; text: string }

type State = { text: string; cursor: number }


// The cursor's line and column, and the offset of a line and column.
function where(text: string, cursor: number): { line: number; column: number } {
  const before = text.slice(0, cursor).split('\n')

  return { line: before.length - 1, column: (before[before.length - 1] ?? '').length }
}

function offset(text: string, line: number, column: number): number {
  const lines = text.split('\n')
  const at = Math.max(0, Math.min(line, lines.length - 1))
  let sum = 0
  for (let n = 0; n < at; n += 1) sum += (lines[n] ?? '').length + 1

  return sum + Math.min(column, (lines[at] ?? '').length)
}

// The editor's next state for one key, and whether the key adds the answer.
export function edit(state: State, key: ClientKeyEvent): { state: State; submit: boolean } {
  const { text, cursor } = state
  const put = (s: string) => ({ state: { text: text.slice(0, cursor) + s + text.slice(cursor), cursor: cursor + s.length }, submit: false })
  const move = (to: number) => ({ state: { text, cursor: Math.max(0, Math.min(text.length, to)) }, submit: false })
  const { line, column } = where(text, cursor)
  switch (key.key) {
    case 'return':
      return key.ctrl === true || key.meta === true ? { state, submit: true } : put('\n')
    case 'backspace':
      return cursor === 0 ? { state, submit: false } : { state: { text: text.slice(0, cursor - 1) + text.slice(cursor), cursor: cursor - 1 }, submit: false }
    case 'delete':
      return { state: { text: text.slice(0, cursor) + text.slice(cursor + 1), cursor }, submit: false }
    case 'left':
      return move(cursor - 1)
    case 'right':
      return move(cursor + 1)
    case 'home':
      return move(offset(text, line, 0))
    case 'end':
      return move(offset(text, line, Number.MAX_SAFE_INTEGER))
    case 'up':
      return move(line === 0 ? 0 : offset(text, line - 1, column))
    case 'down':
      return move(offset(text, line + 1, column))
    case 'space':
      return put(' ')
    default:
      // One character typed; any other name is a key this editor does not use.
      if ([...key.key].length !== 1 || key.ctrl === true || key.meta === true) return { state, submit: false }

      return put(key.key)
  }
}

const Editor: ClientModule<EditorProps, State> = (props, surface) => {
  const { Box, Text } = surface.elements
  const state: State = surface.state ?? { text: '', cursor: 0 }
  surface.onKey(key => {
    const next = edit(surface.state ?? state, key)
    if (next.submit) {
      const text = next.state.text.trim()
      if (text === '') return
      const post: EditorPost = { kind: 'submit', text }
      surface.post(post)
      surface.setState({ text: '', cursor: 0 })
      return
    }
    surface.setState(next.state)
    const post: EditorPost = { kind: 'change', text: next.state.text }
    surface.post(post)
  })
  const lines = state.text.split('\n')
  const { line, column } = where(state.text, state.cursor)

  return (
    <Box flexDirection="column" borderStyle="round" paddingX={1}>
      {state.text === '' ? (
        <Text>
          <Text inverse> </Text>
          <Text dimColor>{props.placeholder}</Text>
        </Text>
      ) : (
        lines.map((l, n) =>
          n === line ? (
            <Text>
              {l.slice(0, column)}
              <Text inverse>{l.slice(column, column + 1) || ' '}</Text>
              {l.slice(column + 1)}
            </Text>
          ) : (
            <Text>{l === '' ? ' ' : l}</Text>
          ),
        )
      )}
      <Text dimColor>Enter: new line · Ctrl+Enter: add</Text>
    </Box>
  )
}

export default Editor

