files.types/index.d.ts:
export type ItemKind = 'question' | 'decision' | 'review'

// open: waiting on the person. ready: answered in the pane, not sent yet.
// looks: something the person wrote seems to answer it; they commit or cancel.
// answered: sent or committed. dismissed: put aside, restorable.
export type ItemStatus = 'open' | 'ready' | 'looks' | 'answered' | 'dismissed'

export type ItemOption = { label: string; verdict: string; reason: string }

// One question, decision or review item, as parsed from a reply. Every text
// field is copied from the reply; '' when the reply has none.
export type Parsed = {
  code: string
  kind: ItemKind
  title: string
  body: string
  // The default or recommendation.
  recommendation: string
  options: ItemOption[]
  // The reply's sentences that explain why the item is asked.
  context: string
  stakes: string
  drivenBy: string
  blocks: string
  // Codes of the items this one feeds, such as ["D1"].
  feeds: string[]
  // The reply's own text for the item.
  source: string
  parsedBy: 'haiku' | 'regex'
}

export type HistoryEntry = { at: number; what: string }

export type ThreadEntry = { who: 'you' | 'fork'; text: string; at: number }

// A tracked item: the turn it came from plus its code is its id.
export type Item = Parsed & {
  id: string
  turnId: string
  // What the round is about: a line from the reply that asked it.
  topic: string
  at: number
  status: ItemStatus
  // The answer: ready to send, sent, or committed.
  answer: string
  // How an answered item was answered.
  how: 'sent' | 'committed' | ''
  // What the person wrote that looks like an answer.
  found: string
  thread: ThreadEntry[]
  history: HistoryEntry[]
}

export type PaneView = {
  tab: 'needs' | 'answered'
  // Cards the person folded (an open card is unfolded by default).
  collapsed: string[]
  // Cards the person unfolded (a ready or answered card is folded by default).
  expanded: string[]
  preview: boolean
  // Items whose Ask is waiting on the fork.
  asking: string[]
  // Items whose Ask thread the person folded.
  foldedThreads: string[]
  // What a running rebuild from the conversation is doing; '' when none runs.
  rebuild: string
}

declare module 'claude-code' {
  interface PluginState {
    // `list` and `pane` replace slice 2's `items` and `view`, whose items had
    // fewer fields: a reload reads the new keys, and takes a saved list from
    // $.store, converted.
    'question-pane': { list: Item[]; pane: PaneView; drafts: Record<string, string> }
  }
}
